export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Engineering ML project</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f4f7fa;color:#172c40;font:17px/1.55 Arial,sans-serif}main{max-width:760px;margin:32px auto;padding:30px;background:#fff;border-radius:12px}\nh1{font-size:28px;line-height:1.2;margin:6px 0 14px}h2{font-size:21px;margin-top:28px}label{display:block;font-weight:bold;margin-top:16px}\ninput{width:100%;padding:12px;border:1px solid #8194a6;border-radius:5px;font:inherit}input[type=checkbox]{width:auto;margin-right:8px}\nbutton,.go{background:#126573;color:#fff;border:0;border-radius:5px;padding:12px 18px;font:inherit;cursor:pointer;text-decoration:none;display:inline-block;margin:10px 6px 6px 0}\nbutton:disabled{opacity:.55;cursor:not-allowed}.muted{color:#526577;font-size:15px}.error{color:#9f251e;font-weight:bold}.ok{color:#1f6b35;font-weight:bold}\n.who{border:2px solid #126573;border-radius:6px;padding:10px 14px;margin-top:10px}.brand{font-size:14px;letter-spacing:1px;font-weight:bold;color:#526577}\ninput:focus,button:focus,.go:focus{outline:3px solid #edab37;outline-offset:3px}[hidden]{display:none!important}\n@media(max-width:650px){main{margin:0;padding:18px 16px;border-radius:0}h1{font-size:25px}.go{display:block;text-align:center}}\n</style></head><body><main>\n<div class=\"brand\">IUEA ENGINEERING ML PROJECT</div><h1 id=\"heading\">Engineering ML project</h1>\n<p><strong>Window:</strong> Monday 23 November 2026, 00:00 to Wednesday 25 November 2026, 23:59 (Kampala time). You have 3 hours from <strong>Start</strong>. Start by Wednesday 25 November 2026, 20:59 to get the full 3 hours.</p>\n<p>Use a laptop, a steady internet connection and the Google account you will use in Colab. Open this page in your normal browser, not inside WhatsApp. Pressing Start begins your 3 hours at once. The time cannot be paused. Coming back to this page later gives you the same notebook and the same deadline.</p>\n<form id=\"identity\" autocomplete=\"off\">\n<label for=\"registration\">Registration number</label>\n<input id=\"registration\" required maxlength=\"40\" placeholder=\"for example 24/351/BSCE-S\" aria-describedby=\"regHelp regResult\">\n<div id=\"regHelp\" class=\"muted\">As on your student card. Spaces and letter case do not matter.</div>\n<div id=\"regResult\" role=\"status\" aria-live=\"polite\"></div>\n<div id=\"whoBox\" class=\"who\" hidden><label for=\"isMe\"><input type=\"checkbox\" id=\"isMe\">This is me: <span id=\"whoName\"></span></label></div>\n<label for=\"email\">Google account email</label>\n<input id=\"email\" type=\"email\" required maxlength=\"254\" autocomplete=\"email\">\n<div class=\"muted\">Your notebook is shared with this account only. Use the same account in Colab. It is recorded with your attempt.</div>\n<button id=\"start\" type=\"submit\" disabled>Start / resume my project</button>\n</form>\n<p id=\"status\" role=\"status\" aria-live=\"polite\"></p>\n<section id=\"ready\" hidden><h2>Your project is ready</h2><a id=\"colab\" class=\"go\" target=\"_blank\" rel=\"noopener\">Open my project in Colab</a>\n<p id=\"timer\" role=\"status\"></p><p id=\"deadline\"></p>\n<ol><li>Run the first cell (your details and the countdown), then <strong>Prepare the data and the libraries</strong>. That cell also starts an automatic backup every 5 minutes.</li>\n<li>Work from top to bottom in this notebook only. It saves itself; press Ctrl+S now and then.</li>\n<li><strong>There is no Submit button.</strong> <span id=\"endText\">At your deadline your editing stops and your work is collected automatically.</span></li></ol>\n<button id=\"checkWork\" type=\"button\">Check my work</button> <button id=\"finish\" type=\"button\">I have finished</button>\n<div id=\"workResult\" role=\"status\" aria-live=\"polite\"></div>\n<p class=\"muted\">Check my work runs your saved notebook from the top on the lecturer's computer and tells you whether it runs, whether every required function and the MEMO form are there, and whether it is the notebook issued to you. It never shows a mark. If something fails, post a screenshot on the class channel at once.</p></section>\n</main><script>\nconst testKey=__TEST_KEY_JSON__;\nconst course=testKey.split('|')[0];\ndocument.getElementById('heading').textContent=course+': Engineering ML project (online, 3 hours)';\nconst onGateway=typeof google==='undefined'||!google.script;\nfunction call(route,body,server){\n if(!onGateway)return new Promise((ok,fail)=>{if(!server)return fail(Error('Open the project link from your lecturer to use this.'));google.script.run.withSuccessHandler(ok).withFailureHandler(fail)[server](body);});\n return fetch(route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json()).then(d=>{if(!d.ok)throw Error(d.error||'Try again.');return d.result;});\n}\nconst reg=document.getElementById('registration'),email=document.getElementById('email'),isMe=document.getElementById('isMe'),start=document.getElementById('start');\nlet checked='',checkTimer,timerInterval,attempt='',pollTimer;\nconst rehearsal=testKey.endsWith('|ML_REHEARSAL');\nif(rehearsal){document.getElementById('heading').textContent=course+': Engineering ML project, REHEARSAL (unmarked)';}\nfunction canStart(){start.disabled=!(checked&&isMe.checked&&email.value.trim());}\nfunction regFormat(v){return /^\\d{2}\\/(UG\\/)?\\d{1,5}\\/[A-Z]{2,8}(-[A-Z]{1,3})?$/.test(v.toUpperCase().replace(/\\s+/g,''));}\nreg.addEventListener('input',()=>{\n checked='';isMe.checked=false;document.getElementById('whoBox').hidden=true;canStart();\n const out=document.getElementById('regResult'),v=reg.value.trim();clearTimeout(checkTimer);out.className='muted';\n if(!v){out.textContent='';return;}\n if(!regFormat(v)){out.textContent='Keep typing. A registration number looks like 24/351/BSCE-S or 23/UG/181/BSCE-J.';}\n else out.textContent='Checking the '+course+' class list...';\n checkTimer=setTimeout(()=>{\n  call('/api/check',{test:testKey,registration:v},'portalCheckRegistration').then(r=>{if(reg.value.trim()!==v)return;checked=r.registration;out.className='ok';out.textContent='Found on the '+course+' class list.';document.getElementById('whoName').textContent=r.nameHint;document.getElementById('whoBox').hidden=false;canStart();})\n  .catch(e=>{if(reg.value.trim()!==v)return;out.className='error';out.textContent=e.message;});\n },regFormat(v)?400:1500);\n});\nisMe.addEventListener('change',canStart);email.addEventListener('input',canStart);\ndocument.getElementById('identity').addEventListener('submit',e=>{\n e.preventDefault();const status=document.getElementById('status');start.disabled=true;status.className='';status.textContent='Preparing your notebook...';\n call('/api/files',{test:testKey,name:'(class list)',email:email.value.trim(),registration:checked},'requestTestFiles').then(r=>{\n  status.textContent=r.resumed?'Welcome back. Your timer is still running from your first start.':'Your 3 hours have started.';\n  const link=document.getElementById('colab');link.href=r.colabUrl;link.textContent=r.resumed?'Resume my project in Colab':'Open my project in Colab';\n  document.getElementById('deadline').textContent=(rehearsal?'Practice deadline (nothing is locked): ':'Your deadline: ')+r.deadline+'.';document.getElementById('ready').hidden=false;\n  attempt=r.attempt||'';if(rehearsal)document.getElementById('endText').textContent='In the rehearsal nothing is locked or marked. Practise Check my work and I have finished.';\n  showStatus();\n  const offset=Date.parse(r.serverNow)-Date.now();clearInterval(timerInterval);\n  const tick=()=>{const left=Math.max(0,Date.parse(r.personalDeadline)-(Date.now()+offset)),s=Math.ceil(left/1000);document.getElementById('timer').textContent=left?'Time left: '+Math.floor(s/3600)+'h '+Math.floor(s%3600/60)+'m '+s%60+'s.':'Your time has ended. Nothing submitted now is marked.';};\n  tick();timerInterval=setInterval(tick,1000);start.disabled=false;\n }).catch(err=>{status.className='error';status.textContent=err.message||'Could not prepare your notebook. Tell your lecturer.';canStart();});\n});\nfunction render(r){\n const out=document.getElementById('workResult');out.className='';out.textContent='';\n const lines=[];\n if(r.state==='collected')lines.push('Your work was collected: '+r.collected.source+', saved '+r.collected.time+' (Kampala time).'+(rehearsal?'':' Editing has stopped.'));\n else if(r.last_backup)lines.push('Last automatic backup received '+r.last_backup+' (Kampala time).');\n if(r.checks){lines.push('Checked '+r.checks.checked+': runs from the top: '+(r.checks.runs_from_top?'yes':'no, first cell that stopped: '+r.checks.first_failed_cell)+'.');\n  lines.push('Required functions found: '+(r.checks.missing_functions.length?'missing '+r.checks.missing_functions.join(', '):'all of them')+'. MEMO form found: '+(r.checks.memo_found?'yes':'no')+'.');\n  if(!r.checks.issued_file)lines.push('This was not the notebook issued to you. Click Resume and work in the issued notebook.');}\n if(r.pending)lines.push('A check is running. This page updates by itself.');\n if(!rehearsal)lines.push(r.mark?'Mark: '+r.mark+'.':'Marks are shown after the window closes and the lecturer releases them.');\n lines.forEach(t=>{const p=document.createElement('p');p.textContent=t;out.appendChild(p);});\n document.getElementById('finish').disabled=r.state==='collected'&&!rehearsal;\n clearTimeout(pollTimer);if(r.pending)pollTimer=setTimeout(showStatus,15000);\n}\nfunction showStatus(){if(!attempt)return;call('/api/status',{attempt}).then(render).catch(()=>{});}\ndocument.getElementById('checkWork').addEventListener('click',()=>{\n const out=document.getElementById('workResult');out.className='';out.textContent='Sending your saved notebook for checking...';\n call('/api/mywork',{attempt}).then(r=>{out.textContent='Checking the version saved '+r.checked_version+'. The result appears here in one to three minutes.';pollTimer=setTimeout(showStatus,15000);})\n .catch(e=>{out.className='error';out.textContent=e.message;showStatus();});\n});\ndocument.getElementById('finish').addEventListener('click',()=>{\n if(!confirm(rehearsal?'Practise finishing? In the rehearsal you can keep working afterwards.':'I have finished: your editing stops now and your work is collected. You cannot continue. Are you sure?'))return;\n const out=document.getElementById('workResult');out.className='';out.textContent='Collecting your work...';\n call('/api/finish',{attempt}).then(render).catch(e=>{out.className='error';out.textContent=e.message;});\n});\n</script></body></html>\n";
